import type { PlaceCategory } from '../types.js';

export interface StarterOpenPoi {
  destinationSlug: string;
  refId: string;
  name: string;
  aliases: string[];
  category: PlaceCategory;
  subtype: string;
  lat: number;
  lng: number;
  address: string;
  description: string;
  whyVisit: string;
  typicalDurationMins: number;
  dietaryHints: string[];
  wikidataId: string | null;
  wikipediaTitle: string | null;
  popularity: number;
}

function p(
  destinationSlug: string,
  refId: string,
  name: string,
  category: PlaceCategory,
  subtype: string,
  lat: number,
  lng: number,
  address: string,
  description: string,
  opts: {
    aliases?: string[];
    whyVisit?: string;
    typicalDurationMins?: number;
    dietaryHints?: string[];
    wikidataId?: string | null;
    wikipediaTitle?: string | null;
    popularity?: number;
  } = {}
): StarterOpenPoi {
  return {
    destinationSlug,
    refId,
    name,
    aliases: opts.aliases ?? [],
    category,
    subtype,
    lat,
    lng,
    address,
    description,
    whyVisit: opts.whyVisit ?? description,
    typicalDurationMins:
      opts.typicalDurationMins ?? (category === 'food' || category === 'cafe' ? 60 : 90),
    dietaryHints: opts.dietaryHints ?? [],
    wikidataId: opts.wikidataId ?? (refId.match(/^wd:(Q\d+)$/)?.[1] ?? null),
    wikipediaTitle: opts.wikipediaTitle ?? null,
    popularity: opts.popularity ?? 0.88,
  };
}

